    let (mut left, mut right) = (0, values.len().saturating_sub(1));
    while left < right {
        match (values[left] + values[right]).cmp(&target) {
            std::cmp::Ordering::Less => left += 1,
            std::cmp::Ordering::Greater => right -= 1,
            std::cmp::Ordering::Equal => return true,
        }
    }
    false
}

